import{j as e,B as t}from"./index-CcymnleV.js";import"./router-Dl48Owdf.js";import{L as o}from"./LegalPage-DJ6EQ3cT.js";import"./vendor-DEQ385Nk.js";import"./seo-DlChPyvh.js";import"./PageHeader-C1KdJQW0.js";const a=[{title:"Who we are",body:[`This website is operated by ${t.legalName} ("the firm", "we", "us"), ${t.addressText}. We act as a Data Fiduciary for personal data you share with us through this website, in accordance with the Digital Personal Data Protection Act, 2023 ("DPDP Act").`]},{title:"Information we collect",body:["We collect only what you choose to share and what is technically necessary to operate the website:",["Contact details you submit through the enquiry form, email, phone or WhatsApp — such as your name, email address, phone number and the nature of your requirement.","Technical information automatically sent by your browser, such as IP address, device and browser type, pages visited and referring site, used in aggregate to keep the website secure and working."],"Please do not send PAN, Aadhaar, bank details or financial documents through the website form. Documents required for an engagement are collected separately through secure channels once you engage the firm."]},{title:"How we use your information",body:[["To respond to your enquiry and arrange a consultation you have requested.","To deliver professional services once you have engaged the firm, including statutory filings on government portals.","To comply with legal, regulatory and professional obligations, including those prescribed by the Institute of Chartered Accountants of India.","To maintain the security and performance of this website."],"We do not sell or rent personal data, and we do not use it for unsolicited marketing."]},{title:"Sharing of information",body:["Personal data is shared only where necessary — with government authorities and portals when filing on your behalf, with service providers that host or deliver our website and email (bound by confidentiality), or where required by law."]},{title:"Retention",body:["Enquiry data is kept only as long as needed to respond to you. Engagement records are retained for the periods required under tax laws, company law and ICAI requirements, after which they are securely deleted."]},{title:"Your rights",body:["Under the DPDP Act you may request access to, correction or erasure of your personal data, withdraw consent, and nominate another person to exercise these rights. To do so, write to us at the email below. You may also approach the Data Protection Board of India if a grievance is not resolved."]},{title:"Security and professional confidentiality",body:["In addition to reasonable technical and organisational safeguards, information received in the course of professional engagements is protected by the confidentiality obligations in the Chartered Accountants Act, 1949 and the ICAI Code of Ethics."]},{title:"Cookies and third-party content",body:["This website uses browser storage only to remember your acceptance of the disclaimer. Embedded content such as Google Maps and links to WhatsApp are governed by those providers’ own privacy policies."]},{title:"Changes and grievance contact",body:[`We may update this policy from time to time; the date above shows the latest revision. For any privacy question or grievance, contact us at ${t.email} or ${t.phone}.`]}],r=()=>e.jsx(o,{path:"/privacy-policy",title:"Privacy",accent:"Policy",updated:"October 2026",intro:`How ${t.name} collects, uses and protects personal data shared through this website.`,sections:a});export{r as default};
